/* gohud glossary — generated by tools/make_site.py. Do not edit by hand. */
window.GLOSSARY={".tres":{"d":"A Godot resource saved as text — readable, and it diffs in git.","k":"file"},".tscn":{"d":"A Godot scene saved as text.","k":"file"},"Button":{"d":"A pressable control. Each state (normal, hover, pressed, disabled, focus) uses a different StyleBox.","k":"node","u":"https://docs.godotengine.org/en/stable/classes/class_button.html"},"CanvasItem":{"d":"Common ancestor of everything drawn in 2D. _draw() lets you put down lines and shapes yourself.","k":"class","u":"https://docs.godotengine.org/en/stable/classes/class_canvasitem.html"},"CanvasLayer":{"d":"A layer pinned to the screen regardless of the camera. HUDs and popups live here.","k":"node","u":"https://docs.godotengine.org/en/stable/classes/class_canvaslayer.html"},"Cinzel":{"d":"The bundled serif heading font. Body text retains the host font; the font includes its SIL Open Font License.","k":"design"},"Control":{"d":"The root of every UI node — position, size, anchors, focus and mouse hit testing.","k":"node","u":"https://docs.godotengine.org/en/stable/classes/class_control.html"},"DPITexture":{"d":"Re-rasterises an SVG to match the screen scale, so icons stay sharp when the UI is enlarged. Added in Godot 4.5 (previously SVGTexture).","k":"resource","u":"https://docs.godotengine.org/en/stable/classes/class_dpitexture.html"},"FoldableContainer":{"d":"A container you collapse and expand by its title row. Added in Godot 4.5.","k":"node","u":"https://docs.godotengine.org/en/stable/classes/class_foldablecontainer.html"},"GDScript":{"d":"Godot's built-in scripting language. gohud is written entirely in it — no build step, no GDExtension.","k":"language","u":"https://docs.godotengine.org/en/stable/tutorials/scripting/gdscript/index.html"},"GitHub Pages":{"d":"GitHub's feature that serves a repository's files as a website. This page is published that way.","k":"service","u":"https://pages.github.com/"},"GoBackPolicy":{"c":"RefCounted","d":"Decides what Escape and the Android Back button close — the topmost surface only.","k":"gohud"},"GoBar":{"c":"Control","d":"A health/mana/experience bar with value, fraction or percent readouts and eased changes.","k":"gohud"},"GoBareButton":{"d":"A type variation name inside the Theme; a node tagged with it is drawn to that spec.","k":"type variation"},"GoButton":{"d":"A type variation name inside the Theme; a node tagged with it is drawn to that spec.","k":"type variation"},"GoCaptionLabel":{"d":"A type variation name inside the Theme; a node tagged with it is drawn to that spec.","k":"type variation"},"GoCard":{"d":"A type variation name inside the Theme; a node tagged with it is drawn to that spec.","k":"type variation"},"GoCoachMark":{"c":"Control","d":"A guided tour pointing at real controls. Pressing the highlighted control advances the tour.","k":"gohud"},"GoCompactButton":{"d":"A type variation name inside the Theme; a node tagged with it is drawn to that spec.","k":"type variation"},"GoCompactLabel":{"d":"A type variation name inside the Theme; a node tagged with it is drawn to that spec.","k":"type variation"},"GoConfig":{"c":"Resource","d":"One settings resource: theme, icons, sizes, surface behaviour, feedback, localization and accessibility. Every field has a working default.","k":"gohud"},"GoDangerButton":{"d":"A type variation name inside the Theme; a node tagged with it is drawn to that spec.","k":"type variation"},"GoDangerSolidButton":{"d":"A type variation name inside the Theme; a node tagged with it is drawn to that spec.","k":"type variation"},"GoDialogs":{"c":"Node","d":"Confirmations and alerts you receive with await.","k":"gohud"},"GoFeedback":{"c":"RefCounted","d":"Haptics and sound cues. gohud ships no audio — the project supplies the sounds.","k":"gohud"},"GoForm":{"c":"MarginContainer","d":"A form that caps its width per breakpoint, avoids the virtual keyboard and guarantees its labels wrap.","k":"gohud"},"GoHudAnchor":{"c":"Control","d":"Pins a HUD piece to one of nine spots, respecting the safe area, with an optional different spot in landscape.","k":"gohud"},"GoIconButton":{"c":"Button","d":"An icon-only button that looks small and presses large.","k":"gohud"},"GoIconSet":{"c":"Resource","d":"A swappable icon set. Widgets ask for icons by name, so a set can be a texture pack, an icon font, or a partial override of another set.","k":"gohud"},"GoJoystick":{"c":"Control","d":"A virtual joystick in fixed, follow or relative mode, reporting a direction and strength of length 0–1.","k":"gohud"},"GoListButton":{"d":"A type variation name inside the Theme; a node tagged with it is drawn to that spec.","k":"type variation"},"GoMicroLabel":{"d":"A type variation name inside the Theme; a node tagged with it is drawn to that spec.","k":"type variation"},"GoNotice":{"c":"PanelContainer","d":"A snackbar that never takes input or focus — a message is read, not pressed.","k":"gohud"},"GoPanel":{"d":"A type variation name inside the Theme; a node tagged with it is drawn to that spec.","k":"type variation"},"GoPrimaryButton":{"d":"A type variation name inside the Theme; a node tagged with it is drawn to that spec.","k":"type variation"},"GoPromptCard":{"c":"PanelContainer","d":"A question card that does not block the screen; the game keeps running behind it.","k":"gohud"},"GoSafeArea":{"c":"Control","d":"Works out the usable rectangle, clear of notches and the gesture bar.","k":"gohud"},"GoScale":{"c":"RefCounted","d":"The dp coordinate system and the breakpoints.","k":"gohud"},"GoScroll":{"c":"ScrollContainer","d":"Touch-friendly scrolling whose scrollbar tucks into the card's existing padding.","k":"gohud"},"GoSheet":{"c":"CanvasLayer","d":"A page that rises from the bottom, on its own CanvasLayer so it sits above the HUD.","k":"gohud"},"GoSkin":{"c":"Resource","d":"The shapes a Theme cannot reach — the joystick, quick-slot faces, the coach-mark ring, chips, dividers. Subclass it and override only what you want to change.","k":"gohud"},"GoSkinMedieval":{"c":"GoSkin","d":"Iron-bound leather and parchment surfaces, restrained rivets, engraved slots and a compass joystick. Other behaviour comes from GoSkin.","k":"gohud"},"GoSkinSciFi":{"c":"GoSkin","d":"The sci-fi shapes: angular panels, a hexagonal joystick, diamond knobs, targeting brackets instead of rings.","k":"gohud"},"GoSlot":{"c":"Button","d":"One quick slot carrying icon, quantity, cooldown and shortcut on a single face, with hit areas shared between crowded neighbours.","k":"gohud"},"GoStyle":{"c":"RefCounted","d":"The widget factory. Building buttons and rows in one place keeps spacing, height and wrapping identical across screens.","k":"gohud"},"GoStyleBoxBracket":{"c":"StyleBox","d":"Marks only the four corners instead of enclosing the content — the targeting bracket of a tactical display.","k":"gohud"},"GoStyleBoxCut":{"c":"StyleBox","d":"A panel with corners cut diagonally, an optional accent edge on one side, and an outer glow — shapes StyleBoxFlat cannot make.","k":"gohud"},"GoStyleBoxMedieval":{"c":"StyleBox","d":"A scalable frame with metal relief, rivets, corner engraving and subtle material grain. Decorations stay in the gutters around content.","k":"gohud"},"GoSubtitleLabel":{"d":"A type variation name inside the Theme; a node tagged with it is drawn to that spec.","k":"type variation"},"GoSurface":{"c":"Control","d":"The shell of a floating window. Popups, sheets and dropdowns all use this one — safe area, virtual keyboard, sticky header and footer, scrolling body, back-button ownership.","k":"gohud"},"GoTheme":{"c":"RefCounted","d":"The names of the theme tokens and how to look them up. Constants instead of strings, so a typo fails to compile rather than returning black.","k":"gohud"},"GoTheme.ACCENT":{"d":"Theme token \"accent\", called as GoTheme.ACCENT in code.","k":"token"},"GoTheme.BACKGROUND":{"d":"Theme token \"background\", called as GoTheme.BACKGROUND in code.","k":"token"},"GoTheme.BORDER":{"d":"Theme token \"border\", called as GoTheme.BORDER in code.","k":"token"},"GoTheme.BOX_CARD":{"d":"Theme token \"card\", called as GoTheme.BOX_CARD in code.","k":"token"},"GoTheme.BOX_EMPTY":{"d":"Theme token \"empty\", called as GoTheme.BOX_EMPTY in code.","k":"token"},"GoTheme.BOX_FOCUS":{"d":"Theme token \"focus\", called as GoTheme.BOX_FOCUS in code.","k":"token"},"GoTheme.BOX_FOCUS_SOFT":{"d":"Theme token \"focus_soft\", called as GoTheme.BOX_FOCUS_SOFT in code.","k":"token"},"GoTheme.BOX_HUD":{"d":"Theme token \"hud\", called as GoTheme.BOX_HUD in code.","k":"token"},"GoTheme.BOX_NOTICE":{"d":"Theme token \"notice\", called as GoTheme.BOX_NOTICE in code.","k":"token"},"GoTheme.BOX_PANEL":{"d":"Theme token \"panel\", called as GoTheme.BOX_PANEL in code.","k":"token"},"GoTheme.BOX_POPUP":{"d":"Theme token \"popup\", called as GoTheme.BOX_POPUP in code.","k":"token"},"GoTheme.BUTTON_HEIGHT":{"d":"Theme token \"button_height\", called as GoTheme.BUTTON_HEIGHT in code.","k":"token"},"GoTheme.COMPACT_PADDING_X":{"d":"Theme token \"compact_padding_x\", called as GoTheme.COMPACT_PADDING_X in code.","k":"token"},"GoTheme.COMPACT_PADDING_Y":{"d":"Theme token \"compact_padding_y\", called as GoTheme.COMPACT_PADDING_Y in code.","k":"token"},"GoTheme.DANGER":{"d":"Theme token \"danger\", called as GoTheme.DANGER in code.","k":"token"},"GoTheme.GAP":{"d":"Theme token \"gap\", called as GoTheme.GAP in code.","k":"token"},"GoTheme.GAP_LARGE":{"d":"Theme token \"gap_large\", called as GoTheme.GAP_LARGE in code.","k":"token"},"GoTheme.GAP_SMALL":{"d":"Theme token \"gap_small\", called as GoTheme.GAP_SMALL in code.","k":"token"},"GoTheme.GAP_TINY":{"d":"Theme token \"gap_tiny\", called as GoTheme.GAP_TINY in code.","k":"token"},"GoTheme.ICON_SIZE":{"d":"Theme token \"icon_size\", called as GoTheme.ICON_SIZE in code.","k":"token"},"GoTheme.INFO":{"d":"Theme token \"info\", called as GoTheme.INFO in code.","k":"token"},"GoTheme.LIST_GLYPH":{"d":"Theme token \"list_glyph\", called as GoTheme.LIST_GLYPH in code.","k":"token"},"GoTheme.MUTED":{"d":"Theme token \"muted\", called as GoTheme.MUTED in code.","k":"token"},"GoTheme.NOTICE_DURATION_MS":{"d":"Theme token \"notice_duration_ms\", called as GoTheme.NOTICE_DURATION_MS in code.","k":"token"},"GoTheme.ON_ACCENT":{"d":"Theme token \"on_accent\", called as GoTheme.ON_ACCENT in code.","k":"token"},"GoTheme.PADDING":{"d":"Theme token \"padding\", called as GoTheme.PADDING in code.","k":"token"},"GoTheme.PADDING_COMPACT":{"d":"Theme token \"padding_compact\", called as GoTheme.PADDING_COMPACT in code.","k":"token"},"GoTheme.RADIUS":{"d":"Theme token \"radius\", called as GoTheme.RADIUS in code.","k":"token"},"GoTheme.RADIUS_LARGE":{"d":"Theme token \"radius_large\", called as GoTheme.RADIUS_LARGE in code.","k":"token"},"GoTheme.RADIUS_SMALL":{"d":"Theme token \"radius_small\", called as GoTheme.RADIUS_SMALL in code.","k":"token"},"GoTheme.SCREEN_MARGIN":{"d":"Theme token \"screen_margin\", called as GoTheme.SCREEN_MARGIN in code.","k":"token"},"GoTheme.SCRIM":{"d":"Theme token \"scrim\", called as GoTheme.SCRIM in code.","k":"token"},"GoTheme.SCROLLBAR_WIDTH":{"d":"Theme token \"scrollbar_width\", called as GoTheme.SCROLLBAR_WIDTH in code.","k":"token"},"GoTheme.SCROLL_DEADZONE":{"d":"Theme token \"scroll_deadzone\", called as GoTheme.SCROLL_DEADZONE in code.","k":"token"},"GoTheme.SCROLL_EDGE":{"d":"Theme token \"scroll_edge\", called as GoTheme.SCROLL_EDGE in code.","k":"token"},"GoTheme.SECONDARY":{"d":"Theme token \"secondary\", called as GoTheme.SECONDARY in code.","k":"token"},"GoTheme.SHADOW":{"d":"Theme token \"shadow\", called as GoTheme.SHADOW in code.","k":"token"},"GoTheme.SUCCESS":{"d":"Theme token \"success\", called as GoTheme.SUCCESS in code.","k":"token"},"GoTheme.SURFACE":{"d":"Theme token \"surface\", called as GoTheme.SURFACE in code.","k":"token"},"GoTheme.SURFACE_HIGH":{"d":"Theme token \"surface_high\", called as GoTheme.SURFACE_HIGH in code.","k":"token"},"GoTheme.SURFACE_SOFT":{"d":"Theme token \"surface_soft\", called as GoTheme.SURFACE_SOFT in code.","k":"token"},"GoTheme.TEXT":{"d":"Theme token \"text\", called as GoTheme.TEXT in code.","k":"token"},"GoTheme.TOUCH":{"d":"Theme token \"touch\", called as GoTheme.TOUCH in code.","k":"token"},"GoTheme.TRACK":{"d":"Theme token \"track\", called as GoTheme.TRACK in code.","k":"token"},"GoTheme.WARNING":{"d":"Theme token \"warning\", called as GoTheme.WARNING in code.","k":"token"},"GoThemePreset":{"c":"Resource","d":"A theme, a skin and an icon set bundled as the unit you pick.","k":"gohud"},"GoThemePresets":{"c":"RefCounted","d":"The registry mapping preset names to resources, including the six gohud ships.","k":"gohud"},"GoTitleLabel":{"d":"A type variation name inside the Theme; a node tagged with it is drawn to that spec.","k":"type variation"},"GoUi":{"c":"RefCounted","d":"The single entry point. Config, theme, skin, icons and strings all come from here, and every function is static — no autoload required.","k":"gohud"},"Node":{"d":"Everything in Godot inherits this. One thing living in the scene tree.","k":"node","u":"https://docs.godotengine.org/en/stable/classes/class_node.html"},"PanelContainer":{"d":"Lays down one background panel and puts children inside it. gohud's cards are these.","k":"node","u":"https://docs.godotengine.org/en/stable/classes/class_panelcontainer.html"},"ProgressBar":{"d":"Shows a value as a bar. Uses two StyleBoxes — background and fill.","k":"node","u":"https://docs.godotengine.org/en/stable/classes/class_progressbar.html"},"ProjectSettings":{"d":"Project-wide settings. gohud adds fields here for its config resource path and preset name.","k":"class","u":"https://docs.godotengine.org/en/stable/classes/class_projectsettings.html"},"RTL":{"d":"Languages read right to left (Arabic, Hebrew). The whole layout mirrors.","k":"concept"},"RenderingServer":{"d":"The low-level drawing interface. Custom StyleBoxes use it to draw polygons and lines.","k":"server","u":"https://docs.godotengine.org/en/stable/classes/class_renderingserver.html"},"Resource":{"d":"Data saved to a file and shared between places. A .tres is one.","k":"class","u":"https://docs.godotengine.org/en/stable/classes/class_resource.html"},"SVG":{"d":"A drawing made of lines and shapes, so it stays sharp at any size. Used for icons.","k":"format"},"ScrollContainer":{"d":"Scrolls its contents when they overflow.","k":"node","u":"https://docs.godotengine.org/en/stable/classes/class_scrollcontainer.html"},"StyleBox":{"d":"Draws one layer of background for a Control — a button's panel, a card's border.","k":"resource","u":"https://docs.godotengine.org/en/stable/classes/class_stylebox.html"},"StyleBoxEmpty":{"d":"A StyleBox that draws nothing. Used to remove a panel.","k":"resource","u":"https://docs.godotengine.org/en/stable/classes/class_styleboxempty.html"},"StyleBoxFlat":{"d":"The engine's built-in StyleBox: solid fill, border, rounded corners, shadow. Rounded is the only corner it has — you cannot cut one diagonally.","k":"resource","u":"https://docs.godotengine.org/en/stable/classes/class_styleboxflat.html"},"Theme":{"d":"One resource holding colours, fonts, spacing and StyleBoxes. Assign it to a Control and everything below it is drawn to that spec.","k":"resource","u":"https://docs.godotengine.org/en/stable/classes/class_theme.html"},"WCAG":{"d":"The web accessibility guidelines — the international baseline for things like colour contrast.","k":"accessibility","u":"https://www.w3.org/WAI/standards-guidelines/wcag/"},"alert_tint":{"d":"How far an alert box's panel is tinted toward its status colour. Default 0.1, a dial of GoSkin.","k":"skin dial"},"alpha compositing":{"d":"Laying a translucent colour over what is behind it to get the colour actually shown on screen. Do this before measuring contrast — measuring the raw colour reports a better ratio than the screen shows.","k":"accessibility"},"autoload":{"d":"A node created at startup and alive for the whole run. gohud works without one.","k":"concept","u":"https://docs.godotengine.org/en/stable/tutorials/scripting/singletons_autoload.html"},"badge_edge_alpha":{"d":"Edge opacity of a badge's panel. Default 0.6, a dial of GoSkin.","k":"skin dial"},"badge_pad_x":{"d":"Horizontal inner padding (dp) of a badge (quantity, time left). Default 5, a dial of GoSkin.","k":"skin dial"},"badge_pad_y":{"d":"Vertical inner padding (dp) of a badge. Default 1, a dial of GoSkin.","k":"skin dial"},"bevel":{"d":"A sloped edge suggested by a highlight and shadow, making the frame look raised.","k":"design"},"bevel_strength":{"d":"Strength of the metal highlight along quick-slot edges. Default 0.18, a dial of GoSkinMedieval.","k":"skin dial"},"bracket_arm":{"d":"Arm length (dp) of the coach mark's targeting bracket. Default 12.0, a dial of GoSkinSciFi.","k":"skin dial"},"bracket_thickness":{"d":"Line thickness (dp) of the coach mark's targeting bracket. Default 2.0, a dial of GoSkinSciFi.","k":"skin dial"},"breakpoint":{"d":"The screen widths separating phone, tablet and desktop. gohud uses 576dp and 991dp.","k":"concept"},"chamfer":{"d":"A corner cut off diagonally rather than rounded. The sci-fi presets' panels use these.","k":"concept"},"chip_edge_alpha":{"d":"Edge opacity of a chip's panel. Default 0.45, a dial of GoSkin.","k":"skin dial"},"chip_fill_alpha":{"d":"Fill opacity of a chip's panel. Default 0.16, a dial of GoSkin.","k":"skin dial"},"contrast ratio":{"d":"How far apart two colours are in brightness. WCAG asks 4.5:1 for body text, 3:1 for large text. Below that, text disappears in daylight.","k":"accessibility","u":"https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html"},"cut_alert":{"d":"Chamfer size (dp) of an alert box. Default 8.0, a dial of GoSkinSciFi.","k":"skin dial"},"cut_chip":{"d":"Chamfer size (dp) of a chip's panel. Default 7.0, a dial of GoSkinSciFi.","k":"skin dial"},"cut_disc_ratio":{"d":"Chamfer of avatars and discs = diameter × this ratio. Default 0.24, a dial of GoSkinSciFi.","k":"skin dial"},"cut_segment":{"d":"Chamfer size (dp) of a segmented control. Default 8.0, a dial of GoSkinSciFi.","k":"skin dial"},"cut_skeleton":{"d":"Chamfer size (dp) of a skeleton panel. Default 5.0, a dial of GoSkinSciFi.","k":"skin dial"},"cut_slot":{"d":"Chamfer size (dp) of a quick-slot panel. Default 6.0, a dial of GoSkinSciFi.","k":"skin dial"},"default_dark":{"d":"One of the presets gohud ships; pass this name to GoUi.use_preset().","k":"preset"},"default_light":{"d":"One of the presets gohud ships; pass this name to GoUi.use_preset().","k":"preset"},"dp":{"d":"A length independent of screen density, so a 48dp button is finger-sized on any device.","k":"unit"},"engraving":{"d":"Fine lines cut into a material; the medieval icons suggest this with silhouettes and etched details.","k":"design"},"float_glow_size":{"d":"Glow distance (dp) of a floating panel that glows instead of casting a shadow, like the sci-fi chamfered panel. Default 10.0, a dial of GoSkin.","k":"skin dial"},"float_shadow_alpha":{"d":"Shadow opacity of floating cards (coach mark, prompt card). Default 0.45, a dial of GoSkin.","k":"skin dial"},"float_shadow_lift":{"d":"Downward offset (dp) of a floating card's shadow. Default 4, a dial of GoSkin.","k":"skin dial"},"float_shadow_size":{"d":"Shadow blur (dp) of floating cards. Default 14, a dial of GoSkin.","k":"skin dial"},"floating panel":{"d":"The backing panel of a HUD or popup drawn over the game. You cannot know what will be behind it, so if it is translucent the text on it must stay readable over the worst backdrop — pure white and pure black.","k":"concept"},"haptics":{"d":"A short vibration so a press is felt, not just seen.","k":"concept"},"joystick_base_alpha":{"d":"Opacity of the joystick's base disc. Default 0.42, a dial of GoSkin.","k":"skin dial"},"joystick_ring_alpha":{"d":"Opacity of the joystick's ring. Default 0.45, a dial of GoSkin.","k":"skin dial"},"joystick_ring_width":{"d":"Width (dp) of the joystick's ring. Default 2.0, a dial of GoSkin.","k":"skin dial"},"leather_grain_alpha":{"d":"Opacity of the subtle leather marks inside quick slots. Default 0.035, a dial of GoSkinMedieval.","k":"skin dial"},"medieval_dark":{"d":"One of the presets gohud ships; pass this name to GoUi.use_preset().","k":"preset"},"medieval_light":{"d":"One of the presets gohud ships; pass this name to GoUi.use_preset().","k":"preset"},"ornament_scale":{"d":"Scale of the metal decorations at quick-slot corners. Menu frames use shape.ornament_scale. Default 1.0, a dial of GoSkinMedieval.","k":"skin dial"},"parchment":{"d":"A warm, pale writing surface inspired by historical manuscripts. Here it is a palette and subtle grain, keeping the text readable.","k":"design"},"preset":{"d":"A theme, a skin and an icon set picked as one unit, so one line changes the whole look.","k":"gohud"},"rivet":{"d":"A small metal fastening head. The medieval frame uses these as restrained corner decorations.","k":"design"},"safe area":{"d":"The part of the screen actually usable, clear of notches, rounded corners and the gesture bar.","k":"concept"},"scifi_dark":{"d":"One of the presets gohud ships; pass this name to GoUi.use_preset().","k":"preset"},"scifi_light":{"d":"One of the presets gohud ships; pass this name to GoUi.use_preset().","k":"preset"},"scrim":{"d":"The translucent veil behind a popup, telling you the layer behind it is not usable right now.","k":"concept"},"skin":{"d":"The resource deciding the shape of things a Theme cannot reach — the joystick, quick slots, the coach mark.","k":"gohud"},"slot_border_idle":{"d":"Quick-slot border width (dp) at rest. Default 1, a dial of GoSkin.","k":"skin dial"},"slot_border_lit":{"d":"Quick-slot border width (dp) while its cooldown runs. Default 2, a dial of GoSkin.","k":"skin dial"},"slot_glow_alpha":{"d":"Glow opacity of a slot whose cooldown is running. Default 0.45, a dial of GoSkinSciFi.","k":"skin dial"},"slot_glow_size":{"d":"Glow distance (dp) of a slot whose cooldown is running. Default 6.0, a dial of GoSkinSciFi.","k":"skin dial"},"slot_radius":{"d":"Corner radius (dp) of the medieval quick-slot frame. Default 4.0, a dial of GoSkinMedieval.","k":"skin dial"},"slot_rivets":{"d":"Show small metal rivets on quick slots: 0 hides them, 1 shows them. Default 1, a dial of GoSkinMedieval.","k":"skin dial"},"slot_tint_idle":{"d":"Accent tint of a quick-slot panel at rest. Default 0.08, a dial of GoSkin.","k":"skin dial"},"slot_tint_lit":{"d":"Accent tint of a quick-slot panel while its cooldown runs. Default 0.24, a dial of GoSkin.","k":"skin dial"},"token":{"d":"Calling a colour or a size by name instead of a number — accent, gap. Names follow along when you swap the theme; numbers do not.","k":"concept"},"touch target":{"d":"The smallest area a finger can reliably press — Material asks 48dp, Apple 44pt. It need not match the visible size.","k":"concept"},"type variation":{"d":"A name inside a Theme that gives one kind of node a different look. A PanelContainer tagged GoCard draws as a card; one without it draws as a plain panel.","k":"concept"}};
